library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all; library std; use std.env.all;
entity tb_bbq_barrel_shifter_core is end;architecture sim of tb_bbq_barrel_shifter_core is signal d,q:std_logic_vector(7 downto 0);signal s:std_logic_vector(3 downto 0);signal dir,arith,rot:std_logic;begin dut:entity work.bbq_barrel_shifter_core generic map(WIDTH=>8)port map(d,s,dir,arith,rot,q);process begin d<=x"81";s<=x"1";dir<='0';arith<='0';rot<='0';wait for 1 ns;assert q=x"02" severity failure;rot<='1';wait for 1 ns;assert q=x"03" severity failure;report "PASS" severity note;stop;wait;end process;end;
